async function api<T>(url:string,method='GET',body?:unknown):Promise<T>{const r=await fetch(url,{method,headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store'});const value=await r.json();if(!r.ok)throw Error(value.error||'Falha de comunicação com o servidor');return value as T;}
function Status({value}:{value:string}){return <span className={'admin-status '+(['PAID','COMPLETED','DELIVERED','CONFIRMED','READY','AVAILABLE'].includes(value)?'green':['CANCELED','REFUNDED','FAILED','OFFLINE'].includes(value)?'red':'amber')}>{statLabel[value]||paymentLabel[value]||value}</span>}
function Empty({message}:{message:string}){return <div className="admin-empty"><ClipboardList size={34}/><strong>{message}</strong><p>Os dados reais aparecerão aqui assim que forem registrados.</p></div>}
function Btn({children,onClick,disabled=false,primary=false}:{children:React.ReactNode;onClick?:()=>void;disabled?:boolean;primary?:boolean}){return <button type="button" className={'admin-btn '+(primary?'primary':'')} onClick={onClick} disabled={disabled}>{children}</button>}
function Metric({label,value,detail,icon:Icon}:{label:string;value:string|number;detail?:string;icon:typeof Activity}){return <div className="admin-card admin-metric"><span className="admin-metric-icon"><Icon size={19}/></span><span>{label}</span><strong>{value}</strong><small>{detail||'Dados do sistema'}</small></div>}
function useResource<T>(url:string,pollEveryMs=0){
  const [data,setData]=useState<T|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState('');
  const refresh=useCallback(async(silent=false)=>{
    if(!silent)setLoading(true);
    try{setData(await api<T>(url));setError('')}
    catch(e){setError(e instanceof Error?e.message:'Erro de conexão')}
    finally{if(!silent)setLoading(false)}
  },[url]);
  useEffect(()=>{void refresh();if(!pollEveryMs)return;
    const timer=setInterval(()=>{if(document.visibilityState==='visible')void refresh(true)},pollEveryMs);
    return()=>clearInterval(timer);
  },[refresh,pollEveryMs]);
  return {data,loading,error,refresh:()=>refresh(),setData};
}
