  const timer=setTimeout(async()=>{try{const res=await fetch('/api/delivery/quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({address:{street,number,neighborhood,city:'São José do Rio Preto',state:'SP'},subtotalCents:lines.reduce((total,x)=>total+x.unitCents*x.qty,0)}),signal:ac.signal});const data=await res.json();if(!res.ok)throw Error(data.error||'Taxa indisponível');if(!ac.signal.aborted)setFee(data.quote.feeCents)}catch(e){if(!ac.signal.aborted){setFee(null);setFeeError(e instanceof Error?e.message:'Não foi possível calcular o frete.')}}finally{if(!ac.signal.aborted)setFeeLoading(false)}},500);
