  const draft={source:'POS',kind,customerName:customer.trim()||'Cliente balcão',customerPhone:phone.trim(),tableToken:kind==='DINE_IN'?table:undefined,paymentMethod:payment,discountCents,address:kind==='DELIVERY'?{street,number,neighborhood,city:'São José do Rio Preto',state:'SP'}:undefined,items:lines.map(x=>({menuItemId:x.id,quantity:x.qty,modifiers:x.modifiers}))};
