 {kind==='DELIVERY'&&<><label className="admin-label full">Rua<input value={street} onChange={e=>setStreet(e.target.value)}/></label><label className="admin-label">Número<input value={number} onChange={e=>setNumber(e.target.value)}/></label><label className="admin-label">Bairro<input value={neighborhood} onChange={e=>setNeighborhood(e.target.value)}/></label></>}
