 {lines.map(it=><div className="admin-quick-item" key={it.key}><img className="admin-preview-img" alt="" src={it.imageUrl}/><div><b>{it.qty}× {it.name}</b><small>{it.details.join(' · ')||'Sem adicionais'}</small><small>{cash(it.unitCents*it.qty)}</small></div><div className="admin-actions"><button className="admin-btn" onClick={()=>setLines(v=>v.map(x=>x.key===it.key?{...x,qty:x.qty-1}:x).filter(x=>x.qty>0))}>−</button><button className="admin-btn" onClick={()=>setLines(v=>v.map(x=>x.key===it.key?{...x,qty:Math.min(30,x.qty+1)}:x))}>+</button></div></div>)}
